1413   if (auto ImpliedCondition =
1414           checkCondition(CmpToCheck->getPredicate(), CmpToCheck->getOperand(0),
1415                          CmpToCheck->getOperand(1), CmpToCheck, Info, CB.NumIn,
1416                          CB.NumOut, CB.getContextInst())) {
