637   // new entry to NewVariables.
638   DenseMap<Value *, unsigned> NewIndexMap;
639   auto GetOrAddIndex = [&Value2Index, &NewVariables,
640                         &NewIndexMap](Value *V) -> unsigned {
641     auto V2I = Value2Index.find(V);
